/// The calls Go makes of the host, on the main thread.
public protocol HostCalls: AnyObject {
    /// the app's bundle and the system's settings, asked once at start
    func appInfo() -> AppInfoReply
    /// the appearance and the accessibility preferences
    func theme() -> ThemeReply
    /// the appearance the app asks for: "light", "dark" or "system"
    func setAppearance(_ c: SetAppearanceCall)
    /// the screen's size in DIPs and scale
    func screen() -> ScreenReply
    /// a line the app wrote to its standard output or error
    func log(_ c: LogCall)
    /// the screen's content: a web view, or a surface for native UI
    func createWindow(_ c: CreateWindowCall) -> CreateWindowReply
    func showWindow(_ c: ShowWindowCall)
    func hideWindow(_ c: HideWindowCall)
    func closeWindow(_ c: CloseWindowCall)
    func setBackground(_ c: SetBackgroundCall)
    func focus(_ c: FocusCall)
    func loadURL(_ c: LoadURLCall)
    func loadHTML(_ c: LoadHTMLCall)
    func reload(_ c: ReloadCall)
    func stopLoading(_ c: StopLoadingCall)
    func goBack(_ c: GoBackCall)
    func goForward(_ c: GoForwardCall)
    func eval(_ c: EvalCall)
    /// runs Body as an async function's; AsyncResult answers
    func callAsync(_ c: CallAsyncCall)
    func setZoom(_ c: SetZoomCall)
    func setUserAgent(_ c: SetUserAgentCall)
    func setUserScripts(_ c: SetUserScriptsCall)
    /// a PNG of the page; Captured answers
    func capturePage(_ c: CapturePageCall)
    func userAgent(_ c: UserAgentCall) -> UserAgentReply
    /// the status and headers of a SchemeRequest (Header: names and values in turn)
    func schemeRespond(_ c: SchemeRespondCall)
    func schemeData(_ c: SchemeDataCall)
    func schemeFinish(_ c: SchemeFinishCall)
    func schemeFail(_ c: SchemeFailCall)
    /// an alert; MessageBoxResult answers
    func messageBox(_ c: MessageBoxCall)
    /// the system's picker of documents; FilesResult answers with copies the app may read
    func openFiles(_ c: OpenFilesCall)
    /// the share sheet of a file, as the place to save it
    func shareFile(_ c: ShareFileCall)
    func clipboardText() -> ClipboardTextReply
    func setClipboardText(_ c: SetClipboardTextCall)
    /// opens a URL in the app the system has for it
    func openURL(_ c: OpenURLCall) -> OpenURLReply
    func secretGet(_ c: SecretGetCall) -> SecretGetReply
    func secretSet(_ c: SecretSetCall) -> SecretSetReply
    func secretDelete(_ c: SecretDeleteCall) -> SecretDeleteReply
    /// a local notification; NotifyDone answers once the system has it
    func notify(_ c: NotifyCall)
    func removeNotification(_ c: RemoveNotificationCall)
    func removeAllNotifications()
    /// keeps the screen on while the app shows
    func keepAwake(_ c: KeepAwakeCall)
    /// "selection", "light", "medium", "heavy", "success", "warning" or "error"
    func haptic(_ c: HapticCall)
    /// asks for a Frame at the next refresh of the display
    func requestFrame(_ c: RequestFrameCall)
    /// where the caret of the text being edited is, and whether the keyboard shows for it
    func setTextInput(_ c: SetTextInputCall)
    /// the text around the caret changed, which the keyboard's suggestions read again
    func textInputChanged(_ c: TextInputChangedCall)
    /// the pointer's shape, for a mouse or a trackpad
    func setCursor(_ c: SetCursorCall)
    /// the tree of accessible elements changed; Focus names the one with the focus
    func accessibilityChanged(_ c: AccessibilityChangedCall)
    func announce(_ c: AnnounceCall)
    /// the system's edit menu at a point, with the actions given (cut, copy, paste, selectAll and labels); MenuChosen answers
    func showMenu(_ c: ShowMenuCall)
    /// shapes Text in Font (Android): glyph IDs, advances and offsets, as Minikin does for a TextView
    func shape(_ c: ShapeCall) -> ShapeReply
    /// draws glyphs of a font file into a mask (Android): their coverage, a byte per pixel
    func drawGlyphs(_ c: DrawGlyphsCall) -> DrawGlyphsReply
}

/// Runs a call on h and encodes its reply, nil for a call not waited for.
public func dispatchCall(_ h: HostCalls, _ buf: UnsafeRawBufferPointer) -> [UInt8]? {
    var r = WireReader(buf)
    var w = WireWriter()
    switch r.uvarint() {
    case 1:
        h.appInfo().encode(&w)
        return w.buf
    case 2:
        h.theme().encode(&w)
        return w.buf
    case 3:
        h.setAppearance(SetAppearanceCall(&r))
        return nil
    case 4:
        h.screen().encode(&w)
        return w.buf
    case 5:
        h.log(LogCall(&r))
        return nil
    case 6:
        h.createWindow(CreateWindowCall(&r)).encode(&w)
        return w.buf
    case 7:
        h.showWindow(ShowWindowCall(&r))
        return nil
    case 8:
        h.hideWindow(HideWindowCall(&r))
        return nil
    case 9:
        h.closeWindow(CloseWindowCall(&r))
        return nil
    case 10:
        h.setBackground(SetBackgroundCall(&r))
        return nil
    case 11:
        h.focus(FocusCall(&r))
        return nil
    case 12:
        h.loadURL(LoadURLCall(&r))
        return nil
    case 13:
        h.loadHTML(LoadHTMLCall(&r))
        return nil
    case 14:
        h.reload(ReloadCall(&r))
        return nil
    case 15:
        h.stopLoading(StopLoadingCall(&r))
        return nil
    case 16:
        h.goBack(GoBackCall(&r))
        return nil
    case 17:
        h.goForward(GoForwardCall(&r))
        return nil
    case 18:
        h.eval(EvalCall(&r))
        return nil
    case 19:
        h.callAsync(CallAsyncCall(&r))
        return nil
    case 20:
        h.setZoom(SetZoomCall(&r))
        return nil
    case 21:
        h.setUserAgent(SetUserAgentCall(&r))
        return nil
    case 22:
        h.setUserScripts(SetUserScriptsCall(&r))
        return nil
    case 23:
        h.capturePage(CapturePageCall(&r))
        return nil
    case 24:
        h.userAgent(UserAgentCall(&r)).encode(&w)
        return w.buf
    case 25:
        h.schemeRespond(SchemeRespondCall(&r))
        return nil
    case 26:
        h.schemeData(SchemeDataCall(&r))
        return nil
    case 27:
        h.schemeFinish(SchemeFinishCall(&r))
        return nil
    case 28:
        h.schemeFail(SchemeFailCall(&r))
        return nil
    case 29:
        h.messageBox(MessageBoxCall(&r))
        return nil
    case 30:
        h.openFiles(OpenFilesCall(&r))
        return nil
    case 31:
        h.shareFile(ShareFileCall(&r))
        return nil
    case 32:
        h.clipboardText().encode(&w)
        return w.buf
    case 33:
        h.setClipboardText(SetClipboardTextCall(&r))
        return nil
    case 34:
        h.openURL(OpenURLCall(&r)).encode(&w)
        return w.buf
    case 35:
        h.secretGet(SecretGetCall(&r)).encode(&w)
        return w.buf
    case 36:
        h.secretSet(SecretSetCall(&r)).encode(&w)
        return w.buf
    case 37:
        h.secretDelete(SecretDeleteCall(&r)).encode(&w)
        return w.buf
    case 38:
        h.notify(NotifyCall(&r))
        return nil
    case 39:
        h.removeNotification(RemoveNotificationCall(&r))
        return nil
    case 40:
        h.removeAllNotifications()
        return nil
    case 41:
        h.keepAwake(KeepAwakeCall(&r))
        return nil
    case 42:
        h.haptic(HapticCall(&r))
        return nil
    case 43:
        h.requestFrame(RequestFrameCall(&r))
        return nil
    case 44:
        h.setTextInput(SetTextInputCall(&r))
        return nil
    case 45:
        h.textInputChanged(TextInputChangedCall(&r))
        return nil
    case 46:
        h.setCursor(SetCursorCall(&r))
        return nil
    case 47:
        h.accessibilityChanged(AccessibilityChangedCall(&r))
        return nil
    case 48:
        h.announce(AnnounceCall(&r))
        return nil
    case 49:
        h.showMenu(ShowMenuCall(&r))
        return nil
    case 50:
        h.shape(ShapeCall(&r)).encode(&w)
        return w.buf
    case 51:
        h.drawGlyphs(DrawGlyphsCall(&r)).encode(&w)
        return w.buf
    default:
        return nil
    }
}

/// Encodes the events the host sends Go.
public enum Event {
    /// the app finished launching
    public static func ready() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(1)
        return w.buf
    }
    /// the app is in front, or no longer
    public static func active(active: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(2)
        w.bool(active)
        return w.buf
    }
    /// the app went to the background (true) or came back
    public static func background(background: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(3)
        w.bool(background)
        return w.buf
    }
    public static func themeChanged() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(4)
        return w.buf
    }
    public static func localeChanged() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(5)
        return w.buf
    }
    public static func openURLs(urls: [String]) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(6)
        w.strings(urls)
        return w.buf
    }
    public static func memoryWarning() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(7)
        return w.buf
    }
    public static func terminating() -> [UInt8] {
        var w = WireWriter()
        w.uvarint(8)
        return w.buf
    }
    /// the window's size in DIPs, the scale, and the insets of what covers it: the system's bars, the cutout, the keyboard
    public static func resized(id: Int, width: Double, height: Double, scale: Double, safeTop: Double, safeLeft: Double, safeBottom: Double, safeRight: Double, keyboard: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(9)
        w.int(id)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(safeTop)
        w.float(safeLeft)
        w.float(safeBottom)
        w.float(safeRight)
        w.float(keyboard)
        return w.buf
    }
    /// Android's back: whether the app took it
    public static func backPressed(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(10)
        w.int(id)
        return w.buf
    }
    /// a message the page's bridge posted
    public static func message(id: Int, text: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(11)
        w.int(id)
        w.string(text)
        return w.buf
    }
    public static func willNavigate(id: Int, url: String, mainFrame: Bool, userInitiated: Bool, unasked: Bool, reload: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(12)
        w.int(id)
        w.string(url)
        w.bool(mainFrame)
        w.bool(userInitiated)
        w.bool(unasked)
        w.bool(reload)
        return w.buf
    }
    /// window.open or a link to _blank: whether the app opened it
    public static func newWindow(id: Int, url: String, userInitiated: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(13)
        w.int(id)
        w.string(url)
        w.bool(userInitiated)
        return w.buf
    }
    /// what the page is at, after any change of it
    public static func pageState(id: Int, url: String, title: String, loading: Bool, canGoBack: Bool, canGoForward: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(14)
        w.int(id)
        w.string(url)
        w.string(title)
        w.bool(loading)
        w.bool(canGoBack)
        w.bool(canGoForward)
        return w.buf
    }
    public static func navigationStarted(id: Int, url: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(15)
        w.int(id)
        w.string(url)
        return w.buf
    }
    public static func navigationCommitted(id: Int, url: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(16)
        w.int(id)
        w.string(url)
        return w.buf
    }
    public static func loadFinished(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(17)
        w.int(id)
        return w.buf
    }
    public static func loadFailed(id: Int, url: String, code: Int, description: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(18)
        w.int(id)
        w.string(url)
        w.int(code)
        w.string(description)
        return w.buf
    }
    public static func closedByPage(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(19)
        w.int(id)
        return w.buf
    }
    public static func processGone(id: Int, reason: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(20)
        w.int(id)
        w.string(reason)
        return w.buf
    }
    public static func permissionRequested(id: Int, kinds: [String], origin: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(21)
        w.int(id)
        w.strings(kinds)
        w.string(origin)
        return w.buf
    }
    /// a request of one of the app's schemes (Header: names and values in turn)
    public static func schemeRequest(id: Int, req: Int, method: String, url: String, header: [String], body: [UInt8], hasBody: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(22)
        w.int(id)
        w.int(req)
        w.string(method)
        w.string(url)
        w.strings(header)
        w.bytes(body)
        w.bool(hasBody)
        return w.buf
    }
    public static func schemeCancel(req: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(23)
        w.int(req)
        return w.buf
    }
    public static func asyncResult(req: Int, result: String, error: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(24)
        w.int(req)
        w.string(result)
        w.string(error)
        return w.buf
    }
    public static func captured(req: Int, png: [UInt8], error: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(25)
        w.int(req)
        w.bytes(png)
        w.string(error)
        return w.buf
    }
    public static func messageBoxResult(req: Int, response: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(26)
        w.int(req)
        w.int(response)
        return w.buf
    }
    public static func filesResult(req: Int, paths: [String], error: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(27)
        w.int(req)
        w.strings(paths)
        w.string(error)
        return w.buf
    }
    public static func notifyDone(req: Int, error: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(28)
        w.int(req)
        w.string(error)
        return w.buf
    }
    public static func notificationClicked(notificationID: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(29)
        w.string(notificationID)
        return w.buf
    }
    /// the display refreshes: draw a frame if one was asked for
    public static func frame(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(30)
        w.int(id)
        return w.buf
    }
    /// the native surface to draw on (a CAMetalLayer, an ANativeWindow), 0 when gone
    public static func surfaceChanged(id: Int, handle: Int, width: Double, height: Double, scale: Double, refresh: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(31)
        w.int(id)
        w.int(handle)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(refresh)
        return w.buf
    }
    /// a finger, a pen or a mouse: Phase is "down", "move", "up" or "cancel", Kind "touch", "pen" or "mouse"
    public static func touch(id: Int, pointer: Int, phase: String, kind: String, x: Double, y: Double, pressure: Double, buttons: Int, time: Double) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(32)
        w.int(id)
        w.int(pointer)
        w.string(phase)
        w.string(kind)
        w.float(x)
        w.float(y)
        w.float(pressure)
        w.int(buttons)
        w.float(time)
        return w.buf
    }
    /// a mouse's or a trackpad's scrolling, in DIPs
    public static func scroll(id: Int, x: Double, y: Double, dx: Double, dy: Double, precise: Bool, phase: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(33)
        w.int(id)
        w.float(x)
        w.float(y)
        w.float(dx)
        w.float(dy)
        w.bool(precise)
        w.string(phase)
        return w.buf
    }
    /// a hardware keyboard's key: Down, its name (as ui names keys) and the text it types
    public static func key(id: Int, down: Bool, key: String, text: String, mods: Int, repeated: Bool) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(34)
        w.int(id)
        w.bool(down)
        w.string(key)
        w.string(text)
        w.int(mods)
        w.bool(repeated)
        return w.buf
    }
    /// the keyboard typed Text, in place of the marked text if any
    public static func textInsert(id: Int, text: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(35)
        w.int(id)
        w.string(text)
        return w.buf
    }
    /// the input method's text being composed, its selection in runes
    public static func textMarked(id: Int, text: String, selStart: Int, selEnd: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(36)
        w.int(id)
        w.string(text)
        w.int(selStart)
        w.int(selEnd)
        return w.buf
    }
    /// the keyboard deleted Before runes before the caret and After after it
    public static func textDelete(id: Int, before: Int, after: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(37)
        w.int(id)
        w.int(before)
        w.int(after)
        return w.buf
    }
    /// an editing action of the keyboard or the edit menu: "newline", "tab", "cut", "copy", "paste", "selectAll", "left", …
    public static func textCommand(id: Int, command: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(38)
        w.int(id)
        w.string(command)
        return w.buf
    }
    /// the text around the caret and the selection, in runes, for the keyboard's suggestions
    public static func textState(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(39)
        w.int(id)
        return w.buf
    }
    /// the keyboard moved the caret or the selection, by runes from the caret
    public static func textSelect(id: Int, start: Int, end: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(40)
        w.int(id)
        w.int(start)
        w.int(end)
        return w.buf
    }
    /// the keyboard went away
    public static func textInputEnded(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(41)
        w.int(id)
        return w.buf
    }
    public static func menuChosen(id: Int, req: Int, action: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(42)
        w.int(id)
        w.int(req)
        w.string(action)
        return w.buf
    }
    /// the accessible elements, encoded as Nodes: for each, its ID, parent, role, label, value, hint, frame and actions
    public static func accessibilityTree(id: Int) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(43)
        w.int(id)
        return w.buf
    }
    /// an assistive technology's action on an element: "press", "increment", "decrement", "focus", "scrollForward", …
    public static func accessibilityAction(id: Int, node: Int, action: String) -> [UInt8] {
        var w = WireWriter()
        w.uvarint(44)
        w.int(id)
        w.int(node)
        w.string(action)
        return w.buf
    }
}

public struct BackPressedReply {
    public var handled: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        handled = r.bool()
    }
}

public struct WillNavigateReply {
    public var allow: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        allow = r.bool()
    }
}

public struct NewWindowReply {
    public var handled: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        handled = r.bool()
    }
}

public struct PermissionRequestedReply {
    public var allow: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        allow = r.bool()
    }
}

public struct KeyReply {
    public var handled: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        handled = r.bool()
    }
}

public struct TextStateReply {
    public var before: String = ""
    public var selected: String = ""
    public var after: String = ""
    public var marked: Int = 0
    public var caretX: Double = 0
    public var caretY: Double = 0
    public var caretHeight: Double = 0
    public init() {}
    init(_ r: inout WireReader) {
        before = r.string()
        selected = r.string()
        after = r.string()
        marked = r.int()
        caretX = r.float()
        caretY = r.float()
        caretHeight = r.float()
    }
}

public struct AccessibilityTreeReply {
    public var nodes: [UInt8] = []
    public init() {}
    init(_ r: inout WireReader) {
        nodes = r.bytes()
    }
}

public struct AccessibilityActionReply {
    public var handled: Bool = false
    public init() {}
    init(_ r: inout WireReader) {
        handled = r.bool()
    }
}
